package com.lexorion.payroll.tenant;import org.springframework.beans.factory.annotation.Value;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.http.HttpHeaders;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;@Component public class PlatformPayrollAuthorityClient implements PayrollAuthorityClient{private final RestClient client;private final String serviceToken;public PlatformPayrollAuthorityClient(@Qualifier("serviceRestClientBuilder") RestClient.Builder builder,@Value("${lexorion.platform-service-url}")String url,@Value("${lexorion.service-auth.payroll-token}")String serviceToken){client=builder.baseUrl(url).build();this.serviceToken=serviceToken;}public TrustedPayrollContext validate(String key,String token,String host,String slug){return client.get().uri("/internal/payroll/workspaces/{key}/context",key).header(HttpHeaders.AUTHORIZATION,token).header(HttpHeaders.HOST,host).header("X-Lexorion-Service-Token",serviceToken).headers(h->{if(slug!=null)h.set("X-Lexorion-Organization",slug);}).retrieve().body(TrustedPayrollContext.class);}}
